function initProceduralTextures() {
  sharedTextures.roofCorrugated = createCorrugatedTexture('#334155', '#1e293b');
  sharedTextures.roofTile = createTileTexture('#475569', '#334155');
  sharedTextures.roofGreenTile = createTileTexture('#226b48', '#14432c');
  sharedTextures.roofOrangeTile = createTileTexture('#d97706', '#9a3412');
  sharedTextures.corrugatedSilver = createCorrugatedTexture('#94a3b8', '#64748b');
  sharedTextures.solar = createSolarTexture();
  sharedTextures.asphalt = createAsphaltTexture();
  sharedTextures.grass = createGrassTexture();
  sharedTextures.helipad = createHelipadTexture();
  sharedTextures.basketballCourt = createBasketballCourtTexture();
  sharedTextures.disabledParking = createDisabledParkingTexture();
  sharedTextures.roadArrow = createRoadArrowTexture();
  sharedTextures.hospitalSign = createHospitalSignTexture();
  sharedTextures.speedBump = createSpeedBumpTexture();
  sharedTextures.opdRoofSign = createOpdRoofSignTexture();
  sharedTextures.kingPortrait = createKingPortraitTexture();
  sharedTextures.tiles = sharedTextures.roofTile;
  sharedTextures.erEmergencySign = createErEmergencySignTexture();
  sharedTextures.erCanopyBeamSign = createErCanopyBeamSignTexture();
  sharedTextures.klumPhueanSign = createKlumPhueanSignTexture();
  sharedTextures.wwtpPondSign = createWwtpPondSignTexture();
}

function createCorrugatedTexture(baseHex, ridgeHex) {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const ctx = c.getContext('2d');
  ctx.fillStyle = baseHex;
  ctx.fillRect(0, 0, 64, 64);
  for (let x = 0; x < 64; x += 4) {
    const grad = ctx.createLinearGradient(x, 0, x + 4, 0);
    grad.addColorStop(0, ridgeHex);
    grad.addColorStop(0.5, 'rgba(255,255,255,0.18)');
    grad.addColorStop(1, ridgeHex);
    ctx.fillStyle = grad;
    ctx.fillRect(x, 0, 4, 64);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(6, 6);
  return tex;
}

function createTileTexture(baseHex, shadowHex) {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const ctx = c.getContext('2d');
  ctx.fillStyle = baseHex;
  ctx.fillRect(0, 0, 64, 64);
  for (let y = 0; y < 64; y += 8) {
    ctx.fillStyle = shadowHex;
    ctx.fillRect(0, y, 64, 2);
    ctx.fillStyle = 'rgba(255,255,255,0.14)';
    ctx.fillRect(0, y + 2, 64, 1);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(4, 4);
  return tex;
}

function createSolarTexture() {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#0f2742';
  ctx.fillRect(0, 0, 64, 64);
  ctx.strokeStyle = '#2b5887';
  ctx.lineWidth = 1;
  for (let i = 0; i <= 64; i += 16) {
    ctx.beginPath();
    ctx.moveTo(i, 0); ctx.lineTo(i, 64);
    ctx.moveTo(0, i); ctx.lineTo(64, i);
    ctx.stroke();
  }
  ctx.strokeStyle = '#94bce8';
  for (let x of [8, 24, 40, 56]) {
    ctx.beginPath();
    ctx.moveTo(x, 0); ctx.lineTo(x, 64);
    ctx.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(3, 2);
  return tex;
}

function createAsphaltTexture() {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#374151';
  ctx.fillRect(0, 0, 128, 128);
  for (let i = 0; i < 500; i++) {
    const x = Math.random() * 128;
    const y = Math.random() * 128;
    ctx.fillStyle = Math.random() > 0.5 ? '#2b323c' : '#4b5563';
    ctx.fillRect(x, y, 1, 1);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(8, 8);
  return tex;
}

function createGrassTexture() {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#416b3d';
  ctx.fillRect(0, 0, 128, 128);
  for (let i = 0; i < 400; i++) {
    const x = Math.random() * 128;
    const y = Math.random() * 128;
    ctx.fillStyle = Math.random() > 0.5 ? '#365832' : '#4e7c49';
    ctx.fillRect(x, y, 2, 2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(12, 12);
  return tex;
}

function createHelipadTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(0, 0, 256, 256);
  ctx.strokeStyle = '#facc15';
  ctx.lineWidth = 10;
  ctx.strokeRect(12, 12, 232, 232);
  ctx.fillStyle = '#dc2626';
  ctx.beginPath();
  ctx.arc(128, 128, 92, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(128, 128, 84, 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 84px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('H', 128, 128);
  return new THREE.CanvasTexture(c);
}

function createBasketballCourtTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 512;
  const ctx = c.getContext('2d');

  // Red perimeter border
  ctx.fillStyle = '#b91c1c';
  ctx.fillRect(0, 0, 256, 512);

  // Green main playing court
  ctx.fillStyle = '#15803d';
  ctx.fillRect(16, 24, 224, 464);

  // White boundary lines
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 3.5;
  ctx.strokeRect(16, 24, 224, 464);

  // Half-court line
  ctx.beginPath();
  ctx.moveTo(16, 256); ctx.lineTo(240, 256);
  ctx.stroke();

  // Center circle
  ctx.beginPath();
  ctx.arc(128, 256, 36, 0, Math.PI * 2);
  ctx.stroke();

  // North Key (Top)
  ctx.fillStyle = '#b91c1c';
  ctx.fillRect(96, 24, 64, 72);
  ctx.strokeRect(96, 24, 64, 72);
  ctx.beginPath();
  ctx.arc(128, 96, 32, 0, Math.PI * 2);
  ctx.stroke();
  // 3-point arc North
  ctx.beginPath();
  ctx.arc(128, 48, 84, 0.25 * Math.PI, 0.75 * Math.PI);
  ctx.stroke();

  // South Key (Bottom)
  ctx.fillStyle = '#b91c1c';
  ctx.fillRect(96, 416, 64, 72);
  ctx.strokeRect(96, 416, 64, 72);
  ctx.beginPath();
  ctx.arc(128, 416, 32, 0, Math.PI * 2);
  ctx.stroke();
  // 3-point arc South
  ctx.beginPath();
  ctx.arc(128, 464, 84, 1.25 * Math.PI, 1.75 * Math.PI);
  ctx.stroke();

  return new THREE.CanvasTexture(c);
}

function createDisabledParkingTexture() {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#0284c7';
  ctx.fillRect(0, 0, 128, 128);
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 6;
  ctx.strokeRect(6, 6, 116, 116);
  // Head
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(68, 36, 10, 0, Math.PI * 2);
  ctx.fill();
  // Body and wheel
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(58, 76, 22, 0.4 * Math.PI, 1.8 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(68, 50);
  ctx.lineTo(68, 74);
  ctx.lineTo(88, 74);
  ctx.lineTo(88, 96);
  ctx.stroke();
  return new THREE.CanvasTexture(c);
}

function createRoadArrowTexture() {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 128;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 64, 128);
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.moveTo(32, 12);
  ctx.lineTo(10, 52);
  ctx.lineTo(24, 52);
  ctx.lineTo(24, 116);
  ctx.lineTo(40, 116);
  ctx.lineTo(40, 52);
  ctx.lineTo(54, 52);
  ctx.closePath();
  ctx.fill();
  return new THREE.CanvasTexture(c);
}

